            // 2. Attach premium 3D tilt tracking animations on interactive cards
            $('.card-interactive').each(function() {
                var card = this;

                // Track mouse position relative to boundaries
                $(card).on('mousemove', function(e) {
                    var rect = card.getBoundingClientRect();
                    var x = e.clientX - rect.left; // x coordinate inside boundaries
                    var y = e.clientY - rect.top;  // y coordinate inside boundaries

                    var xc = rect.width / 2;
                    var yc = rect.height / 2;

                    // Max 8 degrees skew rotation
                    var rx = -((y - yc) / yc) * 6;
                    var ry = ((x - xc) / xc) * 6;

                    // Smoothly update visual variables
                    card.style.setProperty('--rx', rx.toFixed(2) + 'deg');
                    card.style.setProperty('--ry', ry.toFixed(2) + 'deg');
                    card.style.setProperty('--mx', ((x / rect.width) * 100).toFixed(1) + '%');
                    card.style.setProperty('--my', ((y / rect.height) * 100).toFixed(1) + '%');
                    card.style.setProperty('--scale', '1.025');
                    card.style.setProperty('--shadow-intensity', '0.25');
                });

                // Elastic spring physics reset on mouseout
                $(card).on('mouseleave', function() {
                    card.style.setProperty('--rx', '0deg');
                    card.style.setProperty('--ry', '0deg');
                    card.style.setProperty('--mx', '50%');
                    card.style.setProperty('--my', '50%');
                    card.style.setProperty('--scale', '1');
                    card.style.setProperty('--shadow-intensity', '0.1');
                });
            });
